''','''export const DEFAULT_PAGE_SIZE = 50;
export const MAX_PAGE_SIZE = 200;

export interface TaskPage {
  tasks: Task[];
  total: number;
  limit: number;
  offset: number;
}

/** One page of tasks: open ones first (newest first), then completed ones (latest completion first). */
export function listTasks(
  db: Database,
  { limit = DEFAULT_PAGE_SIZE, offset = 0 }: { limit?: number; offset?: number } = {},
): TaskPage {
  const tasks = db.all(
    "SELECT * FROM tasks ORDER BY completed_at IS NOT NULL, completed_at DESC, id DESC LIMIT ? OFFSET ?",
    limit,
    offset,
  ) as unknown as Task[];
  const [{ total }] = db.all("SELECT COUNT(*) AS total FROM tasks") as { total: number }[];
  return { tasks, total, limit, offset };
}
''')
