cat > public/app.js <<'EOF'
const PAGE_SIZE = 50;

const form = document.getElementById("task-form");
const titleInput = document.getElementById("task-title");
const list = document.getElementById("task-list");
const emptyState = document.getElementById("empty-state");
const pager = document.getElementById("pager");
const prevButton = document.getElementById("prev-page");
const nextButton = document.getElementById("next-page");
const pageStatus = document.getElementById("page-status");

let offset = 0;

async function showTasks() {
  const response = await fetch(`/api/tasks?limit=${PAGE_SIZE}&offset=${offset}`);
  const { tasks, total } = await response.json();

  // The last page can vanish when tasks are deleted elsewhere: step back to the new last page.
  if (tasks.length === 0 && total > 0) {
    offset = Math.floor((total - 1) / PAGE_SIZE) * PAGE_SIZE;
    return showTasks();
  }

  list.replaceChildren(
    ...tasks.map((task) => {
      const item = document.createElement("li");
      item.textContent = task.title;
      return item;
    }),
  );
  emptyState.hidden = total > 0;
  pager.hidden = total <= PAGE_SIZE;
  prevButton.disabled = offset === 0;
  nextButton.disabled = offset + PAGE_SIZE >= total;
  pageStatus.textContent = `Page ${offset / PAGE_SIZE + 1} of ${Math.ceil(total / PAGE_SIZE)}`;
}

prevButton.addEventListener("click", () => {
  offset = Math.max(0, offset - PAGE_SIZE);
  showTasks();
});

nextButton.addEventListener("click", () => {
  offset += PAGE_SIZE;
  showTasks();
});

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  await fetch("/api/tasks", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title: titleInput.value }),
  });
  titleInput.value = "";
  offset = 0; // the new task is the newest open one, so it sits on the first page
  await showTasks();
});

showTasks();
EOF
